-- Original level-60 raid quests for the TBC Anniversary client.
-- Quest IDs, factions, prerequisites and locations: Questie TBC data + TBC fixes.
-- Reward IDs, qualities and material counts cross-checked against CMaNGOS TBC DB.
-- https://github.com/Questie/Questie  https://github.com/cmangos/tbc-db
-- Includes historical gate-opening quests, explicitly marked where unavailable.
local _, FDJ = ...
FDJ = FDJ or _G.ForeverDungeonJournal_NS
if not FDJ or not FDJ.IS_TBC_ANNIVERSARY or not FDJ.DB then return end
FDJ.QUEST_PREREQ_CHAINS = FDJ.QUEST_PREREQ_CHAINS or {}
FDJ.QUEST_PREREQ_DETAILS = FDJ.QUEST_PREREQ_DETAILS or {}
FDJ.PREREQ_REWARD_ITEMS_FALLBACK = FDJ.PREREQ_REWARD_ITEMS_FALLBACK or {}
FDJ.CLASSIC_ERA_QUEST_SHAREABILITY_AUDIT = FDJ.CLASSIC_ERA_QUEST_SHAREABILITY_AUDIT or {}
-- Optional explanations do not block progress. anyOf represents a single
-- prerequisite satisfied by one of several mutually exclusive quest IDs.
function FDJ.IsQuestChainStepComplete(step, predicate, skipOptional)
    if not step then return false end
    if skipOptional and step.optional then return true end
    if step.id and predicate(step.id) then return true end
    if step.alt and predicate(step.alt) then return true end
    for _, id in ipairs(step.anyOf or {}) do
        if predicate(id) then return true end
    end
    return false
end
