quests[7507] = {id = 7507, name = "Foror's Compendium", faction = "Both", requires = 60, level = 60, vanillaRaidQuest = true, pickup = "Foror's Compendium of Dragon Slaying - Loot from Tsu'zee, Prince Tortheldrin, Magister Kalendris, Illyanna Ravenoak, Tendris Warpwood, A Dusty Tome, A Dusty Tome and other enemies. Right-click the item to begin.", startItem = {[1] = 18401, [2] = "Foror's Compendium of Dragon Slaying", [3] = 4, [4] = "Loot from Tsu'zee, Prince Tortheldrin, Magister Kalendris, Illyanna Ravenoak, Tendris Warpwood, A Dusty Tome, A Dusty Tome and other enemies. Right-click the item to begin."}, startsInDungeon = true, turnin = "Lorekeeper Lydros - inside the Athenaeum library, beneath Dire Maul North / accessible from Dire Maul West; avoid attacking the neutral scholars", turninNPC = 14368, shareable = false, repeatable = false, rewardSpellID = 22925, rewardSummary = "Shen'dralar +200", objective = "Return Foror's Compendium of Dragon Slaying to the Athenaeum.", note = "", requiredItems = {{[1] = 18401, [2] = "Foror's Compendium of Dragon Slaying", [3] = 4, count = 1}}}
quests[7508] = {id = 7508, name = "The Forging of Quel'Serrar", faction = "Both", requires = 60, level = 60, vanillaRaidQuest = true, pickup = "A Dull and Flat Elven Blade - Receive from Lorekeeper Lydros in the Dire Maul Athenaeum after Foror's Compendium; use the blade to start this step.", startItem = {[1] = 18513, [2] = "A Dull and Flat Elven Blade", [3] = 4, [4] = "Receive from Lorekeeper Lydros in the Dire Maul Athenaeum after Foror's Compendium; use the blade to start this step."}, startsInDungeon = true, turnin = "Lorekeeper Lydros - inside the Athenaeum library, beneath Dire Maul North / accessible from Dire Maul West; avoid attacking the neutral scholars", turninNPC = 14368, shareable = false, repeatable = false, objective = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros.", note = "", requiredItems = {{[1] = 18513, [2] = "A Dull and Flat Elven Blade", [3] = 4, count = 1}}}
quests[7509] = {id = 7509, name = "The Forging of Quel'Serrar", faction = "Both", requires = 60, level = 60, vanillaRaidQuest = true, pickup = "Lorekeeper Lydros - inside the Athenaeum library, beneath Dire Maul North / accessible from Dire Maul West; avoid attacking the neutral scholars", startNPC = 14368, startsInDungeon = true, turnin = "Lorekeeper Lydros - inside the Athenaeum library, beneath Dire Maul North / accessible from Dire Maul West; avoid attacking the neutral scholars", turninNPC = 14368, rewardItems = {{[1] = 18348, [2] = "Quel'Serrar", [3] = 4}}, shareable = false, repeatable = true, rewardSummary = "Shen'dralar +200", objective = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.\n\nThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.\n\nDo this and Quel'Serrar will be yours.", note = "Repeatable hand-in; not a daily. Warrior/paladin weapon use. Plant Unfired Ancient Blade for Onyxia's frontal flame, pick up Heated Ancient Blade, then use it on her corpse within its time limit. Return Treated Ancient Blade to Lydros in the Athenaeum.", chainTitle = "The Forging of Quel'Serrar", requiredItems = {{[1] = 18492, [2] = "Treated Ancient Blade", [3] = 1, count = 1}}}
quests[7604] = {id = 7604, name = "A Binding Contract", faction = "Both", requires = 60, level = 60, vanillaRaidQuest = true, pickup = "Thorium Brotherhood Contract - Speak to Lokhtos Darkbargainer in the Grim Guzzler, Blackrock Depths, while carrying a Sulfuron Ingot from Golemagg (Molten Core); obtain and use the contract.", startItem = {[1] = 18628, [2] = "Thorium Brotherhood Contract", [3] = 4, [4] = "Speak to Lokhtos Darkbargainer in the Grim Guzzler, Blackrock Depths, while carrying a Sulfuron Ingot from Golemagg (Molten Core); obtain and use the contract."}, startsInDungeon = true, turnin = "Lokhtos Darkbargainer - inside Blackrock Depths, Grim Guzzler tavern", turninNPC = 12944, rewardItems = {{[1] = 18592, [2] = "Plans: Sulfuron Hammer", [3] = 4}}, shareable = false, repeatable = true, rewardSummary = "Thorium Brotherhood +1000", noteRewardItems = {{[1] = 17182, [2] = "Sulfuras, Hand of Ragnaros", [3] = 5}}, objective = "Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.", note = "Repeatable hand-in; not a daily. Requires Blacksmithing 300 to use Plans: Sulfuron Hammer. The quest exchanges one Sulfuron Ingot from Golemagg for those plans. Sulfuras is made by combining a crafted Sulfuron Hammer with Eye of Sulfuras from Ragnaros; there is no separate Sulfuras reward quest.", requiredItems = {{[1] = 18628, [2] = "Thorium Brotherhood Contract", [3] = 4, count = 1}, {[1] = 17203, [2] = "Sulfuron Ingot", [3] = 4, count = 1}}}
quests[7622] = {id = 7622, name = "The Balance of Light and Shadow", faction = "Both", requires = 60, level = 60, vanillaRaidQuest = true, classOnly = "PRIEST", pickup = "Eris Havenfire - northwest of Stratholme, on the road toward Stratholme's main gate, Eastern Plaguelands; equip The Eye of Divinity to see her (21.0, 18.4)", startNPC = 14494, startsInDungeon = false, startMap = {mapID = 1423, x = 0.2096, y = 0.184, label = "Eris Havenfire - northwest of Stratholme, on the road toward Stratholme's main gate, Eastern Plaguelands; equip The Eye of Divinity to see her", markerType = "quest", npcID = 14494}, map = {mapID = 1423, x = 0.2096, y = 0.184, label = "Eris Havenfire - northwest of Stratholme, on the road toward Stratholme's main gate, Eastern Plaguelands; equip The Eye of Divinity to see her", markerType = "quest", npcID = 14494}, turnin = "Eris Havenfire - northwest of Stratholme, on the road toward Stratholme's main gate, Eastern Plaguelands; equip The Eye of Divinity to see her (21.0, 18.4)", turninNPC = 14494, rewardItems = {{[1] = 18659, [2] = "Splinter of Nordrassil", [3] = 4}}, shareable = false, repeatable = false, noteRewardItems = {{[1] = 18608, [2] = "Benediction", [3] = 4}, {[1] = 18609, [2] = "Anathema", [3] = 4}}, objective = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\n\nYou may view the Death Post to view how many Peasants have been slain.", note = "Priest epic chain: equip The Eye of Divinity from Majordomo's Cache of the Firelord to see Eris. Save 50 peasants before 15 die; do the event without outside assistance. Combine the reward Splinter of Nordrassil with The Eye of Divinity and The Eye of Shadow to create Benediction, which can transform into Anathema. These staves are created by combining items, not direct quest rewards.", chainTitle = "The Balance of Light and Shadow", startRequirementItem = {[1] = 18646, [2] = "The Eye of Divinity", [3] = 4, [4] = "Loot from the Cache of the Firelord after Majordomo Executus in Molten Core. Equip it to see Eris Havenfire and begin the priest challenge."}}
quests[7632] = {id = 7632, name = "The Ancient Leaf", faction = "Both", requires = 60, level = 60, vanillaRaidQuest = true, classOnly = "HUNTER", pickup = "Ancient Petrified Leaf - Ancient Petrified Leaf from Cache of the Firelord after Majordomo Executus in Molten Core; right-click the leaf.", startItem = {[1] = 18703, [2] = "Ancient Petrified Leaf", [3] = 4, [4] = "Ancient Petrified Leaf from Cache of the Firelord after Majordomo Executus in Molten Core; right-click the leaf."}, startsInDungeon = true, turnin = "Vartrus the Ancient - Irontree Woods hill, northern Felwood; present the Ancient Petrified Leaf to awaken the Ancients (47.8, 24.1)", turninNPC = 14524, turninMap = {mapID = 1448, x = 0.4778, y = 0.2408, label = "Vartrus the Ancient - Irontree Woods hill, northern Felwood; present the Ancient Petrified Leaf to awaken the Ancients", markerType = "quest", npcID = 14524}, shareable = false, repeatable = false, objective = "Find the owner of the Ancient Petrified Leaf. Good luck, adventurer; It's a big world.", note = "Hunter only. The leaf comes from Majordomo Executus's reward chest in Molten Core. Completing this opens three parallel tasks from the Ancients in Felwood.", requiredItems = {{[1] = 18703, [2] = "Ancient Petrified Leaf", [3] = 4, count = 1}}}
quests[7634] = {id = 7634, name = "Ancient Sinew Wrapped Lamina", faction = "Both", requires = 60, level = 60, vanillaRaidQuest = true, classOnly = "HUNTER", pickup = "Hastat the Ancient - Irontree Woods hill, northern Felwood, beside the other Ancients (46.7, 24.1)", startNPC = 14526, startsInDungeon = false, startMap = {mapID = 1448, x = 0.467, y = 0.2406, label = "Hastat the Ancient - Irontree Woods hill, northern Felwood, beside the other Ancients", markerType = "quest", npcID = 14526}, map = {mapID = 1448, x = 0.467, y = 0.2406, label = "Hastat the Ancient - Irontree Woods hill, northern Felwood, beside the other Ancients", markerType = "quest", npcID = 14526}, turnin = "Hastat the Ancient - Irontree Woods hill, northern Felwood, beside the other Ancients (46.7, 24.1)", turninNPC = 14526, rewardItems = {{[1] = 18714, [2] = "Ancient Sinew Wrapped Lamina", [3] = 4}}, shareable = false, repeatable = false, objective = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood.", note = "Optional quiver branch. Mature Blue Dragon Sinew drops from Azuregos, with a rare alternative drop from elite blue dragonkin in Winterspring. This is separate from the bow/string tasks.", chainTitle = "Ancient Sinew Wrapped Lamina", requiredItems = {{[1] = 18704, [2] = "Mature Blue Dragon Sinew", [3] = 4, count = 1}}}
quests[7635] = {id = 7635, name = "A Proper String", faction = "Both", requires = 60, level = 60, vanillaRaidQuest = true, classOnly = "HUNTER", pickup = "Stoma the Ancient - Irontree Woods hill, northern Felwood, beside the other Ancients (48.4, 22.3)", startNPC = 14525, startsInDungeon = false, startMap = {mapID = 1448, x = 0.4839, y = 0.2229, label = "Stoma the Ancient - Irontree Woods hill, northern Felwood, beside the other Ancients", markerType = "quest", npcID = 14525}, map = {mapID = 1448, x = 0.4839, y = 0.2229, label = "Stoma the Ancient - Irontree Woods hill, northern Felwood, beside the other Ancients", markerType = "quest", npcID = 14525}, turnin = "Stoma the Ancient - Irontree Woods hill, northern Felwood, beside the other Ancients (48.4, 22.3)", turninNPC = 14525, rewardItems = {{[1] = 18724, [2] = "Enchanted Black Dragon Sinew", [3] = 4}}, shareable = false, repeatable = false, objective = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood.", note = "Hunter bow-string branch: Mature Black Dragon Sinew drops from Onyxia. Runs in parallel with Stave of the Ancients; neither branch is a prerequisite to accepting the other.", chainTitle = "A Proper String", requiredItems = {{[1] = 18705, [2] = "Mature Black Dragon Sinew", [3] = 4, count = 1}}}
quests[7636] = {id = 7636, name = "Stave of the Ancients", faction = "Both", requires = 60, level = 60, vanillaRaidQuest = true, classOnly = "HUNTER", pickup = "Vartrus the Ancient - Irontree Woods hill, northern Felwood; present the Ancient Petrified Leaf to awaken the Ancients (47.8, 24.1)", startNPC = 14524, startsInDungeon = false, startMap = {mapID = 1448, x = 0.4778, y = 0.2408, label = "Vartrus the Ancient - Irontree Woods hill, northern Felwood; present the Ancient Petrified Leaf to awaken the Ancients", markerType = "quest", npcID = 14524}, map = {mapID = 1448, x = 0.4778, y = 0.2408, label = "Vartrus the Ancient - Irontree Woods hill, northern Felwood; present the Ancient Petrified Leaf to awaken the Ancients", markerType = "quest", npcID = 14524}, turnin = "Vartrus the Ancient - Irontree Woods hill, northern Felwood; present the Ancient Petrified Leaf to awaken the Ancients (47.8, 24.1)", turninNPC = 14524, rewardItems = {{[1] = 18707, [2] = "Ancient Rune Etched Stave", [3] = 4}}, shareable = false, repeatable = false, noteRewardItems = {{[1] = 18713, [2] = "Rhok'delar, Longbow of the Ancient Keepers", [3] = 4}, {[1] = 18715, [2] = "Lok'delar, Stave of the Ancient Keepers", [3] = 4}}, objective = "You must find and destroy these four demonic corrupters:\n\nSimone the Seductress.\n\nKlinfran the Crazed.\n\nSolenor the Slayer.\n\nArtorius the Doombringer.\n\nDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.\n\nRefer to the Petrified Bark in your inventory for clues as to their whereabouts.\n\nYou MUST complete this task by yourself.", note = "Hunter epic weapon branch. Kill Simone (Un'Goro), Klinfran (Burning Steppes), Solenor (Silithus) and Artorius (Winterspring) alone, with no pet or outside assistance. In parallel, complete A Proper String using Onyxia's sinew. Combine Ancient Rune Etched Stave and Enchanted Black Dragon Sinew for Rhok'delar; the Ancients can provide the corresponding Lok'delar staff. The weapons are crafted/converted results, not the quest's direct reward.", chainTitle = "Stave of the Ancients", requiredItems = {{[1] = 18952, [2] = "Simone's Head", [3] = 1, count = 1}, {[1] = 18953, [2] = "Klinfran's Head", [3] = 1, count = 1}, {[1] = 18954, [2] = "Solenor's Head", [3] = 1, count = 1}, {[1] = 18955, [2] = "Artorius's Head", [3] = 1, count = 1}}}
quests[7761] = {id = 7761, name = "Blackhand's Command", faction = "Both", requires = 55, level = 60, vanillaRaidQuest = true, pickup = "Blackhand's Command - Drop from the Scarshield Quartermaster outside Blackrock Spire, in the uninstanced hall near its entrance in Blackrock Mountain; right-click the orders.", startItem = {[1] = 18987, [2] = "Blackhand's Command", [3] = 1, [4] = "Drop from the Scarshield Quartermaster outside Blackrock Spire, in the uninstanced hall near its entrance in Blackrock Mountain; right-click the orders."}, startsInDungeon = false, turnin = "Drakkisath's Brand - inside Upper Blackrock Spire, behind General Drakkisath; touch the glowing orb after his defeat", turninObjectID = 179880, shareable = false, repeatable = false, objective = "That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.\n\nThe letter indicates that General Drakkisath guards the brand. Perhaps you should investigate.", note = "Unlocks the Orb of Command shortcut to Blackwing Lair. Start from the Quartermaster's orders outside Blackrock Spire, then defeat General Drakkisath in UBRS and touch Drakkisath's Brand behind him. Do not confuse the Quartermaster with a boss inside LBRS."}
