quests[7786] = {id = 7786, name = "Thunderaan the Windseeker", faction = "Both", requires = 60, level = 60, vanillaRaidQuest = true, pickup = "Highlord Demitrian - northwestern Silithus, north of the Crystal Vale, near the Thunderaan summoning area (21.7, 8.6)", startNPC = 14347, startsInDungeon = false, startMap = {mapID = 1451, x = 0.2171, y = 0.0857, label = "Highlord Demitrian - northwestern Silithus, north of the Crystal Vale, near the Thunderaan summoning area", markerType = "quest", npcID = 14347}, map = {mapID = 1451, x = 0.2171, y = 0.0857, label = "Highlord Demitrian - northwestern Silithus, north of the Crystal Vale, near the Thunderaan summoning area", markerType = "quest", npcID = 14347}, turnin = "Highlord Demitrian - northwestern Silithus, north of the Crystal Vale, near the Thunderaan summoning area (21.7, 8.6)", turninNPC = 14347, shareable = false, repeatable = false, objective = "To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Windseeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian in Silithus.", note = "Requires BOTH bindings, Essence of the Firelord from Ragnaros while on this quest, and 10 Elementium Bars. Elementium Ore comes from Blackwing Lair; have a miner learn Smelt Elementium from Krixix in BWL. Turn-in summons Thunderaan in Silithus.", requiredItems = {{[1] = 17771, [2] = "Elementium Bar", [3] = 5, count = 10}, {[1] = 19017, [2] = "Essence of the Firelord", [3] = 1, count = 1}, {[1] = 18563, [2] = "Bindings of the Windseeker", [3] = 5, count = 1}, {[1] = 18564, [2] = "Bindings of the Windseeker", [3] = 5, count = 1}}}
