for id, quest in pairs(quests) do
    -- Keep hand-authored dungeon step text/maps where already present; add
    -- missing metadata and supply complete data for every newly added step.
    local details = FDJ.QUEST_PREREQ_DETAILS[id]
    if not details then
        details = {}
        FDJ.QUEST_PREREQ_DETAILS[id] = details
    end
    for key, value in pairs(quest) do
        if details[key] == nil then details[key] = value end
    end
    FDJ.CLASSIC_ERA_QUEST_SHAREABILITY_AUDIT[id] = quest.shareable
    if quest.rewardItems then
        FDJ.PREREQ_REWARD_ITEMS_FALLBACK[id] = {
            items = quest.rewardItems, choice = quest.rewardChoice == true,
        }
    end
end

